    (277, 'npc_0370', 'Diêm Phác', 'Hán Trung Công Tào • Trương Lỗ Mưu Chủ', 14),
    (278, 'npc_0371', 'Dương Tùng', 'Hán Trung Trọng Thần • Tham Kim Đắc Lợi', 14),
    (279, 'npc_0372', 'Dương Nhiệm', 'Hán Trung Đại Tướng • Tử Chiến Tào Sa Trường', 14),
    (280, 'npc_0373', 'Dương Bá', 'Hán Trung Tiên Phong Hiệu Úy • Bạch Thủy Trấn', 14),
    (281, 'npc_0374', 'Trương Vệ', 'Dương Bình Quan Tử Thủ • Trương Lỗ Đệ', 14),
    (282, 'npc_0375', 'Bàng Hi', 'Ba Tây Thái Thú • Ích Châu Lão Thần', 14),
    (283, 'npc_0376', 'Lôi Đồng', 'Thục Hán Tiên Phong Mãnh Tướng • Huyết Chiến Hán Xuyên', 14),
    (284, 'npc_0377', 'Ngô Lan', 'Thục Hán Kỵ Tướng • Phạt Hán Trung Tiên Phong', 14),
    (285, 'npc_0378', 'Ngô Ý (Tử Viễn)', 'Xa Kỵ Tướng Quân • Trấn Hán Trung Đô Đốc', 14),
    (286, 'npc_0379', 'Ngô Ban (Nguyên Hùng)', 'Phiêu Kỵ Tướng Quân • Tiên Phong Di Lăng', 14),
    (287, 'npc_0380', 'Vương Bình (Tử Quân)', 'Trấn Bắc Tướng Quân • Vô Đương Phi Quân Thống Soái', 14),
    (288, 'npc_0381', 'Đặng Chi (Bá Miêu)', 'Đại Tướng Quân • Sứ Ngô Kiệt Xuất Danh Thần', 14),
    (289, 'npc_0382', 'Trương Dực (Bá Cung)', 'Tả Xa Kỵ Tướng Quân • Cương Trực Liêm Khiết', 14),
    (290, 'npc_0383', 'Trương Nguy (Bá Kỳ)', 'Hậu Tướng Quân • Tử Thủ Kiếm Các', 14),
    (291, 'npc_0384', 'Sạn Đạo Lão Phu', 'Lão Luyện Hiểm Đạo Hán Xuyên Ba Thục', 14),
    (292, 'npc_0385', 'Tưởng Uyển (Công Diễm)', 'Đại Tướng Quân Thục Hán • Tứ Anh Thừa Kế Khổng Minh', 15),
    (293, 'npc_0386', 'Phí Y (Văn Vĩ)', 'Thượng Thư Lệnh Thục Hán • Hòa Nhã Túc Trí Tứ Anh', 15),
    (294, 'npc_0387', 'Đổng Doãn (Hưu Chi)', 'Thị Trung Thục Hán • Cương Trực Ngăn Hoạn Quan', 15),
    (295, 'npc_0388', 'Tiêu Chu (Doãn Nam)', 'Thông Nho Bác Cổ • Thục Trung Thái Học Sĩ', 15),
    (296, 'npc_0389', 'Hoàng Quyền (Công Hành)', 'Trấn Nam Tướng Quân • Thao Lược Ba Thục Danh Tướng', 15),
    (297, 'npc_0390', 'Mạnh Đạt (Tử Độ)', 'Thượng Dung Thái Thú • Văn Võ Kiêu Hùng', 15),
    (298, 'npc_0391', 'Lý Nghiêm (Chính Phương)', 'Trung Đô Hộ Thục Hán • Thác Cô Trọng Thần', 15),
    (299, 'npc_0392', 'Tần Mật (Tử Sắc)', 'Biện Thuyết Danh Sĩ • Trí Biện Trương Ôn Vang Danh', 15),
    (300, 'npc_0393', 'Lữ Nghệ (Quý Dương)', 'Thục Hán Thượng Thư Lệnh • Trì Gia Thanh Khiết', 15);

INSERT OR IGNORE INTO np_attribute (npc_id, name_han, style_name_vi, birth_year, war_attr, ldr_attr, int_attr, pol_attr, dip_attr, com_attr, log_attr, cra_attr, con_attr, wil_attr, prc_attr, lck_attr, personality, bio_vi) VALUES
    (128, '曹植', 'Tử Kiến', 192, 35, 60, 92, 70, 78, 55, 65, 95, 60, 80, 90, 75, 'SCHOLARLY', 'Tài hoa xuất chúng thi từ đệ nhất, thất bộ thành thi, nổi danh văn tài thiên cổ thời Tam Quốc.'),
    (129, '曹彰', 'Tử Văn', 189, 91, 85, 60, 50, 55, 45, 65, 45, 88, 86, 60, 72, 'VALIANT', 'Hoàng Tu Nhi võ dũng hơn người, tay không bắt thú dữ, dẹp yên quân Ô Hoàn phương bắc lập đại công.'),
    (130, '卞夫人', 'Vũ Tuyên', 160, 20, 50, 84, 86, 90, 70, 75, 70, 65, 88, 85, 88, 'BENEVOLENT', 'Chính thất của Tào Tháo, sinh mẫu Tào Phi, Tào Chương, Tào Thực; tính tình cần kiệm hiền hậu, an định hậu phương gia tộc.'),
    (131, '华歆', 'Tử Ngư', 157, 30, 65, 86, 90, 85, 75, 80, 55, 62, 85, 82, 78, 'PRAGMATIC', 'Thái úy Tào Ngụy, thông hiểu điển chương chế độ, một đời thanh liêm chính trực, quản trị hình pháp nghiêm cẩn.'),
    (132, '王朗', 'Cảnh Hưng', 152, 25, 60, 88, 89, 86, 68, 76, 50, 58, 75, 84, 76, 'SCHOLARLY', 'Đại thần trải ba triều Tào Ngụy, học vấn uyên thâm bậc đại nho kinh học, trước tác kinh sử lưu truyền hậu thế.'),
    (133, '陈群', 'Trường Văn', 160, 25, 75, 92, 96, 88, 78, 88, 55, 65, 90, 92, 82, 'SCHOLARLY', 'Thượng thư lệnh Tào Ngụy, người khởi xướng Cửu phẩm trung chính chế và Ngụy luật, đặt nền tảng quan chế hàng trăm năm.'),
    (134, '崔琰', 'Quý Khuê', 163, 50, 72, 85, 88, 80, 60, 75, 50, 70, 94, 88, 70, 'HONORABLE', 'Danh sĩ phương bắc dung mạo khôi vĩ, lời nói ngay thẳng mực thước, chủ trì tuyển trạch nhân sĩ chí công vô tư.'),
    (135, '司马师', 'Tử Nguyên', 208, 75, 93, 94, 91, 84, 70, 86, 60, 78, 95, 91, 82, 'PRAGMATIC', 'Con trưởng Tư Mã Ý, tính tình thâm trầm quyết đoán, thống lĩnh cấm quân dẹp yên loạn Hoài Nam, đặt nền móng Tấn triều.'),
    (136, '司马昭', 'Tử Thượng', 211, 70, 91, 95, 93, 88, 75, 88, 62, 75, 94, 93, 85, 'AMBITIOUS', 'Tấn Văn Đế, tài trí thao lược kiệt xuất, điều binh khiển tướng diệt nước Thục Hán, nắm trọn đại quyền thiên hạ.'),
    (137, '苏双', 'Tử Tài', 160, 50, 62, 72, 60, 82, 90, 86, 45, 65, 75, 80, 76, 'PRAGMATIC', 'Đại thương nhân buôn ngựa cự phú vùng Trung Sơn, cùng Trương Thế Bình hiến vàng bạc chiến mã cho Lưu Bị khởi nghiệp.'),
    (138, '马腾', 'Thọ Thành', 156, 86, 87, 60, 58, 65, 55, 75, 50, 90, 85, 68, 72, 'HONORABLE', 'Hậu duệ Phục Ba tướng quân Mã Viện, thân hình hùng tráng, thống lĩnh thiết kỵ Lương Châu uy trấn biên ải.'),
    (139, '韩遂', 'Văn Ước', 150, 80, 85, 82, 72, 75, 65, 78, 50, 82, 80, 78, 70, 'PRAGMATIC', 'Quân phiệt Lương Châu cát cứ nhiều năm, đa mưu xảo trá, xưng hùng Tây Bắc qua nhiều phen biến loạn triều đình.'),
    (140, '阎行', 'Minh Nhạn', 168, 89, 80, 65, 50, 52, 45, 68, 48, 86, 84, 68, 70, 'VALIANT', 'Dũng tướng Lương Châu rể của Hàn Toại, từng dùng mâu đâm suýt giết chết Mã Siêu trong trận kỵ chiến tay đôi.'),
    (141, '庞柔', 'Bá Thuận', 160, 65, 72, 74, 70, 72, 68, 75, 52, 72, 78, 74, 70, 'PRAGMATIC', 'Huynh trưởng của danh tướng Bàng Đức, ngụ cư tại Lương Châu, am tường thế sự và kết giao rộng rãi chư hầu.'),
    (142, '李蒙', 'Thiết Kỵ', 160, 78, 75, 52, 40, 45, 42, 65, 45, 80, 74, 55, 65, 'VALIANT', 'Võ tướng Tây Lương bộ hạ Đổng Trác và Lý Thôi, thiện chiến cưỡi ngựa chém giết nơi quan ải Trường An.'),
    (143, '王方', 'Đại Đao', 160, 79, 74, 48, 38, 42, 40, 62, 45, 82, 72, 52, 64, 'VALIANT', 'Chiến tướng Tây Lương từng nghênh chiến quân Mã Siêu tại Trường An, tác chiến dũng cảm can trường.'),
    (144, '胡车儿', 'Thần Lực', 165, 88, 68, 55, 30, 40, 42, 60, 48, 92, 85, 65, 68, 'VALIANT', 'Dũng sĩ dưới trướng Trương Tú, sức mang ngàn cân đi năm trăm dặm, người lập mưu trộm song kích của Điển Vi.'),
    (145, '沮授', 'Giám Quân', 155, 45, 86, 94, 88, 82, 60, 88, 55, 68, 95, 92, 68, 'SCHOLARLY', 'Mưu thần số một của Viên Thiệu, mưu lược nhìn xa trông rộng, thà chết không chịu đầu hàng Tào Tháo.'),
    (146, '许攸', 'Tử Viễn', 158, 35, 65, 90, 78, 80, 70, 84, 45, 58, 70, 88, 65, 'PRAGMATIC', 'Bạn thuở nhỏ của Tào Tháo, người hiến kế đốt kho lương Ô Sào quyết định thắng bại trận Quan Độ.'),
    (147, '逢纪', 'Nguyên Đồ', 160, 38, 72, 85, 82, 80, 65, 78, 48, 62, 82, 80, 70, 'SCHOLARLY', 'Tâm phúc mưu sĩ của Viên Thiệu, khuyên Thiệu chiếm Ký Châu khai lập cơ nghiệp Hà Bắc.'),
    (148, '郭图', 'Công Tắc', 160, 32, 68, 84, 76, 86, 68, 74, 45, 55, 75, 78, 68, 'PRAGMATIC', 'Mưu sĩ Dĩnh Xuyên theo Viên Thiệu, khéo ăn nói bày kế, từng làm sứ giả chiêu dụ chư hầu phương bắc.'),
    (149, '袁谭', 'Hiển Tư', 173, 75, 78, 65, 68, 66, 60, 72, 48, 76, 75, 62, 65, 'VALIANT', 'Con trưởng Viên Thiệu, dũng mãnh thiện chiến xưng bá Thanh Châu, cùng Tào Tháo giao tranh kiên cường.'),
    (150, '袁熙', 'Hiển Dịch', 176, 62, 72, 68, 70, 74, 65, 70, 50, 70, 72, 65, 68, 'PRAGMATIC', 'Con thứ Viên Thiệu, cai trị U Châu ôn hòa, phu quân ban đầu của Chân Mật trước khi về với Tào Phi.'),
    (151, '袁尚', 'Hiển Phủ', 179, 76, 78, 68, 66, 72, 62, 70, 50, 78, 78, 68, 66, 'VALIANT', 'Con út được Viên Thiệu yêu quý nhất, dung mạo tuấn tú, kế thừa đại nghiệp Hà Bắc quyết chiến Tào Doanh.'),
    (152, '吕威璜', 'Trợ Tướng', 160, 74, 72, 55, 45, 48, 55, 76, 45, 76, 70, 56, 65, 'VALIANT', 'Võ tướng Hà Bắc phò tá Thuần Vu Quỳnh canh giữ Ô Sào, dũng cảm chống đỡ đợt tập kích của Tào Tháo.'),
    (153, '淳于琼', 'Trọng Giản', 152, 78, 80, 62, 58, 60, 58, 78, 50, 80, 72, 58, 64, 'VALIANT', 'Tây Viên Bát Hiệu Úy lừng danh thời Hán Linh Đế cùng Tào Tháo, Viên Thiệu, đại tướng trấn thủ Ô Sào.'),
    (154, '韩猛', 'Kiêu Kỵ', 160, 82, 78, 50, 42, 45, 52, 80, 45, 84, 76, 58, 66, 'VALIANT', 'Dũng tướng phương bắc phụ trách áp tải lương thảo vạn dặm cho đại quân Viên Thiệu tại Quan Độ.'),
    (155, '刘禅', 'Công Tự', 207, 32, 55, 62, 68, 75, 70, 65, 55, 78, 70, 60, 95, 'BENEVOLENT', 'Hậu Chủ Thục Hán, tại vị hơn 40 năm an định thiên tử, phúc hậu may mắn bậc nhất thời Tam Quốc.'),
    (156, '田畴', 'Tử Thái', 169, 72, 80, 84, 82, 78, 65, 88, 55, 80, 92, 86, 75, 'SCHOLARLY', 'Nghĩa sĩ U Châu ẩn cư Từ Vô Sơn trăm họ theo về, dẫn đường cho Tào Tháo xuất Bạch Lang Sơn đại phá Ô Hoàn.'),
    (157, '公孙越', 'Thiết Kỵ', 162, 77, 75, 58, 48, 52, 45, 68, 45, 79, 75, 58, 65, 'VALIANT', 'Em họ Công Tôn Toản, thống lĩnh kỵ binh Bạch Mã dũng mãnh xung trận phạt Đổng và tranh đoạt Dự Châu.'),
    (158, '赵累', 'Trung Nghĩa', 165, 75, 82, 76, 74, 70, 65, 82, 52, 80, 94, 72, 68, 'HONORABLE', 'Đô đốc dưới trướng Quan Vũ, trung can nghĩa đảm quản lý lương nhu quân vụ, theo Quan Công tử chiến đến giọt máu cuối.'),
    (159, '关银屏', 'Hổ Nữ', 198, 86, 80, 70, 58, 65, 50, 70, 50, 84, 90, 72, 75, 'VALIANT', 'Ái nữ của Võ Thánh Quan Vũ, học trọn võ nghệ Quan gia, trảm tướng bình định Nam Trung.'),
    (160, '张星彩', 'Kính Ai', 205, 72, 78, 80, 82, 84, 65, 72, 55, 78, 88, 76, 82, 'BENEVOLENT', 'Trưởng nữ Trương Phi, Hoàng hậu Thục Hán đoan trang dũng lược, bảo hộ ấu chúa và an định hậu cung.'),
    (161, '夏侯霸', 'Trọng Quyền', 190, 85, 83, 75, 68, 70, 55, 78, 52, 82, 86, 75, 74, 'VALIANT', 'Con Hạ Hầu Uyên, võ nghệ cao cường, sau biến cố Cao Bình Lăng sang Thục giúp Khương Duy phạt Bắc.'),
    (162, '梁习', 'Tử Ngu', 160, 40, 76, 84, 91, 80, 82, 88, 60, 68, 86, 84, 76, 'SCHOLARLY', 'Thứ sử Trọng thần Tào Ngụy, trị lý phương bắc ân uy song hành, khôi phục nông nghiệp điền trang sầm uất.'),
    (163, '张宝', 'Địa Công', 160, 76, 80, 81, 65, 74, 55, 68, 52, 60, 78, 74, 70, 'PRAGMATIC', 'Nhị đệ Trương Giác, thống soái nghĩa quân Khăn Vàng Hà Bắc, sử dụng thuật số hô phong hoán vũ kháng cự quân Hán.'),
    (164, '张梁', 'Nhân Công', 160, 75, 79, 80, 62, 72, 54, 66, 50, 60, 76, 72, 68, 'PRAGMATIC', 'Tam đệ Trương Giác, tử thủ Quảng Tông huyết chiến cùng Hoàng Phủ Tung, dũng liệt kiên trinh đến cùng.'),
    (165, '波才', 'Đại Soái', 160, 78, 82, 70, 50, 60, 48, 65, 45, 80, 78, 62, 66, 'VALIANT', 'Thống soái Khăn Vàng vùng Dĩnh Xuyên, từng vây khốn Hoàng Phủ Tung và Chu Tuấn tại Trường Xã.'),
    (166, '张曼成', 'Thần Thượng', 160, 77, 81, 72, 55, 65, 52, 68, 48, 82, 76, 65, 68, 'VALIANT', 'Đại phương Khăn Vàng khởi nghĩa tại Nam Dương chém Thái thú Chử Cống, uy chấn vùng Kinh Châu.'),
    (167, '赵弘', 'Chủ Soái', 160, 75, 76, 68, 48, 55, 50, 65, 45, 80, 74, 60, 65, 'VALIANT', 'Kế tục Trương Mạn Thành tử thủ Uyển Thành nhiều tháng chống đỡ quan quân đại hán.'),
    (168, '韩忠', 'Dũng Tướng', 160, 74, 75, 65, 45, 52, 48, 64, 45, 78, 72, 62, 64, 'VALIANT', 'Tướng lĩnh Khăn Vàng kiên cường tại Uyển Thành, thiện nghệ bắn cung tác chiến.'),
    (169, '孙仲', 'Hiệp Thủ', 160, 73, 74, 62, 42, 50, 46, 62, 42, 76, 70, 58, 62, 'VALIANT', 'Tướng Khăn Vàng dũng mãnh hiệp thủ thành trì, chiến đấu kiên cường cùng quan quân.'),
    (170, '彭脱', 'Đại Suất', 160, 76, 77, 66, 45, 55, 50, 65, 45, 80, 75, 60, 65, 'VALIANT', 'Thống soái Khăn Vàng vùng Nhữ Nam, tập hợp hơn ba vạn nghĩa binh hưởng ứng Hoàng Cân.'),
    (171, '卜己', 'Thủ Lĩnh', 160, 74, 75, 64, 44, 52, 48, 64, 44, 78, 72, 58, 64, 'VALIANT', 'Thủ lĩnh Khăn Vàng chiếm cứ Đông Quận uy hiếp Lạc Dương, dũng mãnh kháng cự Hoàng Phủ Tung.'),
    (172, '管亥', 'Cuồng Đao', 160, 85, 78, 52, 35, 42, 40, 60, 45, 88, 80, 55, 65, 'FIERCE', 'Dũng tướng Khăn Vàng bao vây Khổng Dung tại Bắc Hải, một mình giao đấu kịch liệt với Quan Vũ mấy chục hiệp.'),
    (173, '程远志', 'Phương Suất', 160, 75, 72, 55, 38, 45, 42, 60, 45, 78, 70, 52, 62, 'VALIANT', 'Đại phương suất năm vạn quân Khăn Vàng xâm lấn U Châu, đụng độ ba huynh đệ Lưu Quan Trương trận đầu.'),
    (174, '邓茂', 'Tiên Phong', 160, 72, 68, 50, 35, 40, 40, 58, 42, 76, 68, 50, 60, 'VALIANT', 'Phó tướng tiên phong của Trình Viễn Chí, xung trận kiêu dũng nơi chiến trường U Châu.'),
    (175, '严政', 'Quân Nhu', 160, 60, 68, 72, 65, 68, 62, 75, 55, 65, 70, 68, 65, 'PRAGMATIC', 'Tâm phúc tướng lĩnh của Trương Bảo quản lý quân nhu và tài chính nghĩa quân Khăn Vàng.'),
    (176, '高升', 'Kiêu Tướng', 160, 76, 72, 58, 42, 48, 45, 62, 45, 78, 72, 56, 64, 'VALIANT', 'Võ tướng dưới trướng Trương Bảo, từng xuất trận khiêu chiến quân Hán tại Khúc Dương.'),
    (177, '廖九郎', 'Dược Sư', 160, 35, 52, 78, 60, 72, 65, 70, 85, 62, 75, 78, 70, 'BENEVOLENT', 'Đạo sĩ Thái Bình Đạo thông thạo bùa chú và nam dược, cứu chữa bệnh tật cho dân nghèo Ký Châu.'),
    (178, '马远奇', 'Sơn Sứ', 160, 65, 70, 75, 62, 78, 74, 80, 52, 74, 76, 75, 68, 'PRAGMATIC', 'Sứ giả liên lạc giữa Khăn Vàng và Hắc Sơn quân Trương Yến, thông thạo đường núi và thương lộ ngầm.'),
    (179, '孔融', 'Văn Cử', 153, 35, 68, 89, 86, 92, 65, 75, 60, 62, 92, 88, 78, 'HONORABLE', 'Hậu duệ đời thứ 20 của Khổng Tử, bậc đại danh sĩ Kiến An, khí phách ngút trời, thương dân như con.'),
    (180, '郑玄', 'Khang Thành', 127, 20, 50, 98, 90, 88, 55, 65, 50, 58, 96, 96, 85, 'SCHOLARLY', 'Tông sư kinh học vĩ đại nhất thời Đông Hán, chú giải ngũ kinh, học trò hàng ngàn người khắp thiên hạ.'),
    (181, '太史慈母', 'Hiền Mẫu', 140, 20, 45, 82, 75, 88, 65, 60, 70, 60, 95, 85, 88, 'BENEVOLENT', 'Mẫu thân hiền đức của Thái Sử Từ, răn dạy con lấy trung nghĩa làm đầu, khuyên con cứu viện Khổng Dung đền ơn.'),
    (182, '孙观', 'Nguyên Ba', 165, 82, 80, 65, 55, 58, 50, 70, 50, 84, 82, 65, 70, 'VALIANT', 'Mãnh tướng Thái Sơn dũng mãnh thiện chiến, theo Tàng Bá hàng Tào Tháo, trảm tướng lập công dẹp yên duyên hải.'),
    (183, '吴敦', 'Lục Lâm', 162, 78, 76, 60, 48, 52, 48, 68, 48, 80, 78, 60, 68, 'VALIANT', 'Tướng lĩnh thảo khấu Thái Sơn quy thuận quan phủ, thiện chiến áp chế loạn quân vùng Thanh Châu.'),
    (184, '尹礼', 'Thái Sơn', 165, 77, 76, 62, 52, 55, 50, 68, 48, 80, 76, 62, 68, 'VALIANT', 'Dũng tướng xuất thân Thái Sơn, sau nhậm Đông Hải Thái thú, trị an nghiêm cẩn bảo hộ thương đạo.'),
    (185, '昌豨', 'Đông Hải', 160, 80, 78, 64, 45, 52, 55, 68, 45, 82, 75, 64, 65, 'PRAGMATIC', 'Quân phiệt ven biển Thanh Từ, chiếm cứ địa hình hiểm trở kháng cự nhiều đại tướng Tào Doanh.'),
    (186, '田楷', 'Thanh Châu', 158, 72, 76, 74, 76, 75, 65, 75, 50, 74, 78, 70, 70, 'HONORABLE', 'Thứ sử Thanh Châu cùng Lưu Bị liên minh chống Viên Thiệu, hết mực trung nghĩa phò tá Bắc Bình.'),
    (187, '龚景', 'Sử Quân', 150, 60, 70, 72, 74, 72, 62, 70, 48, 68, 72, 68, 66, 'PRAGMATIC', 'Thứ sử Thanh Châu thời khởi nghĩa Khăn Vàng, gửi thư cầu viện Lưu Bị giải vây thành trì thái bình.'),
    (188, '赵浮', 'Cường Nỗ', 155, 78, 78, 68, 60, 58, 55, 75, 60, 78, 80, 68, 68, 'VALIANT', 'Đô đốc Ký Châu dưới trướng Hàn Phức, thống lĩnh vạn nỏ binh cường kích làm Viên Thiệu kiêng dè.'),
    (189, '耿武', 'Tử Tiết', 155, 65, 74, 78, 78, 65, 55, 72, 50, 72, 88, 74, 65, 'HONORABLE', 'Trung thần Ký Châu cầm đao mắng Viên Thiệu cướp châu quận, trung liệt khí khái lưu danh thiên cổ.'),
    (190, '闵纯', 'Biệt Giá', 156, 60, 72, 76, 78, 68, 58, 70, 48, 70, 86, 72, 66, 'HONORABLE', 'Biệt giá Ký Châu cùng Cảnh Vũ can gián Hàn Phức không nhường Ký Châu cho Viên Thiệu, tử tiết vì nghĩa.'),
    (191, '孙礼', 'Đức Đạt', 180, 84, 85, 76, 84, 78, 65, 80, 55, 86, 88, 75, 76, 'VALIANT', 'Tư đồ Tào Ngụy, từng tay không đâm chết hổ bảo vệ Ngụy Minh Đế, cương trực thanh liêm mẫu mực.'),
    (192, '刘勋', 'Lư Giang', 155, 76, 75, 68, 65, 68, 72, 70, 50, 76, 74, 66, 68, 'PRAGMATIC', 'Thái thú Lư Giang có nhiều binh mã lương thảo tại vùng Hoài Lư, sau hàng Tào Tháo nhậm Bình Lỗ tướng quân.'),
    (193, '崔林', 'Đức Nho', 170, 35, 72, 86, 92, 85, 70, 82, 50, 70, 88, 86, 78, 'SCHOLARLY', 'Tư không Tào Ngụy em họ Thôi Diễm, tính trầm tĩnh khoan hòa, tài năng lớn nở muộn, trị lý trăm họ ấm no.'),
    (194, '曹真', 'Tử Đan', 185, 85, 91, 84, 82, 78, 65, 88, 55, 86, 88, 80, 82, 'VALIANT', 'Đại tướng quân tổng chỉ huy Tào Ngụy nhiều lần chặn đứng Gia Cát Lượng phạt Bắc, yêu thương tướng sĩ, dũng lược cái thế.'),
    (195, '曹休', 'Văn Liệt', 180, 84, 88, 78, 76, 75, 65, 84, 52, 84, 86, 76, 78, 'VALIANT', 'Thiên lý câu của dòng họ Tào, thống lĩnh Hổ Báo Kỵ uy chấn sa trường, đại tư mã khai quốc Tào Ngụy.'),
    (196, '公孙度', 'Thăng Tế', 150, 82, 86, 78, 84, 80, 75, 85, 55, 84, 88, 80, 82, 'AMBITIOUS', 'Hùng bá Liêu Đông mở rộng bờ cõi hải ngoại, chiêu hiền đãi sĩ, xây dựng nền thái bình phương bắc thời loạn.'),
    (197, '公孙康', 'Trảm Lỗ', 175, 80, 82, 76, 80, 82, 70, 80, 52, 82, 82, 75, 78, 'PRAGMATIC', 'Con trưởng Công Tôn Độ, trảm Viên Đàm Viên Thượng dâng đầu cho Tào Tháo, bình định Hàn Quốc dẹp yên biên cương.'),
    (198, '公孙恭', 'Thủ Thành', 180, 65, 72, 70, 74, 76, 68, 72, 50, 68, 72, 70, 70, 'CAUTIOUS', 'Nhị tử Công Tôn Độ cai trị Liêu Đông thời Tào Phi, cẩn trọng giữ gìn bờ cõi hòa bình.'),
    (199, '公孙渊', 'Văn Ý', 205, 80, 82, 78, 72, 75, 70, 78, 55, 82, 84, 76, 70, 'AMBITIOUS', 'Tự xưng Yên Vương tại Liêu Đông, dùng kế qua lại giữa Ngụy và Ngô, kiêu dũng cát cứ phương bắc.'),
    (200, '蹋顿', 'Đơn Vu', 165, 88, 86, 62, 50, 60, 55, 75, 45, 92, 86, 65, 72, 'FIERCE', 'Đơn Vu Ô Hoàn dũng mãnh, được ví như Mạo Đốn thiền vu tái thế, thống lĩnh vạn kỵ binh thảo nguyên.'),
    (201, '丘力居', 'Đại Nhân', 145, 80, 82, 65, 60, 68, 62, 75, 48, 85, 80, 70, 70, 'VALIANT', 'Thủ lĩnh Ô Hoàn thế hệ trước, từng liên minh Trương Thuần khuấy đảo toàn bộ vùng Liêu Tây U Châu.'),
    (202, '难楼', 'Hùng Trưởng', 150, 78, 80, 60, 52, 62, 58, 72, 45, 82, 78, 65, 68, 'VALIANT', 'Hùng trưởng Ô Hoàn vùng Thượng Cốc xưng vương, nắm trong tay hơn chín vạn kỵ binh biên cương.'),
    (203, '苏仆延', 'Tiễu Vương', 155, 80, 80, 62, 50, 60, 56, 72, 45, 84, 78, 64, 68, 'VALIANT', 'Thủ lĩnh Ô Hoàn xưng Tiễu Vương tại Liêu Tây, dũng hãn thiện xạ kỵ binh thảo nguyên.'),
    (204, '张纯', 'Thiên Định', 155, 76, 75, 65, 55, 62, 58, 68, 45, 78, 74, 62, 65, 'AMBITIOUS', 'Thái thú Trung Sơn liên minh Ô Hoàn khởi binh chống Hán, tự phong Thiên Định Vương chấn động phương bắc.'),
    (205, '张举', 'Thiên Tử', 155, 74, 72, 62, 50, 58, 55, 65, 42, 75, 70, 58, 62, 'AMBITIOUS', 'Quan lại U Châu cùng Trương Thuần tạo phản tự xưng Thiên tử, chiếm cứ nhiều quan ải biên giới.'),
    (206, '鲜于辅', 'Biệt Giá', 160, 75, 82, 82, 85, 86, 70, 84, 52, 78, 86, 82, 78, 'HONORABLE', 'Biệt giá U Châu được trăm họ và ngoại tộc hết mực kính trọng, khuyên Lưu Hòa báo thù Công Tôn Toản.'),
    (207, '阎柔', 'Tư Mã', 165, 78, 84, 80, 84, 88, 72, 85, 52, 82, 86, 82, 80, 'SCHOLARLY', 'Từ nhỏ sống giữa người Ô Hoàn Tiên Ti, được các bộ lạc tôn kính như thủ lĩnh, Tào Tháo nhận làm nghĩa tử.'),
    (208, '齐周', 'Tòng Sự', 160, 60, 72, 74, 76, 75, 65, 72, 50, 68, 76, 72, 70, 'HONORABLE', 'Tòng sự dưới trướng U Châu Mục Lưu Ngu, một lòng vì dân, phản đối bạo lực của Công Tôn Toản.'),
    (209, '鲜于银', 'Hiệu Úy', 162, 78, 76, 65, 58, 62, 55, 74, 50, 80, 78, 68, 70, 'VALIANT', 'Tướng lĩnh U Châu dũng cảm can trường, cùng Tiên Vu Phụ trấn thủ biên ải phía bắc kiên cố.'),
    (210, '邹靖', 'Phá Lỗ', 155, 80, 80, 68, 65, 66, 58, 75, 50, 82, 80, 70, 72, 'VALIANT', 'Phá Lỗ hiệu úy dẫn dắt ba huynh đệ Lưu Quan Trương dẹp giặc Khăn Vàng thuở ban đầu lập công khai cơ.'),
    (211, '单于禄马', 'Đại Thương', 158, 45, 62, 70, 65, 80, 88, 86, 60, 68, 75, 82, 76, 'PRAGMATIC', 'Lão thương nhân chuyên buôn bán giống ngựa thượng thặng vùng Liêu Đông Thảo Nguyên, mắt nhìn tuấn mã cực chuẩn.'),
    (212, '轲比能', 'Hùng Chủ', 185, 88, 88, 75, 68, 72, 65, 82, 52, 92, 88, 76, 75, 'AMBITIOUS', 'Thủ lĩnh vĩ đại của người Tiên Ti, thống nhất thảo nguyên phía bắc làm Tào Ngụy nhiều phen kinh sợ.'),
    (213, '陶谦', 'Cung Tổ', 132, 40, 75, 78, 82, 85, 70, 76, 52, 60, 82, 80, 78, 'BENEVOLENT', 'Thứ sử Từ Châu nhân hậu, ba lần nhượng Từ Châu cho Lưu Bị để cứu muôn dân thoát cảnh chiến hỏa đao binh.'),
    (214, '曹豹', 'Từ Châu', 155, 70, 72, 50, 48, 52, 58, 68, 48, 72, 68, 52, 60, 'PRAGMATIC', 'Đại tướng lâu năm của Từ Châu, thông gia cùng Lữ Bố, chỉ huy quân sĩ trấn giữ thành lũy Hạ Phì.'),
    (215, '臧霸', 'Tuyên Cao', 162, 86, 87, 72, 70, 72, 62, 80, 52, 86, 88, 74, 76, 'VALIANT', 'Đại tướng danh tiếng xuất thân Thái Sơn, uy trấn vùng ven biển Từ Châu, Tào Tháo ủy thác toàn quyền miền duyên hải.'),
    (216, '郝萌', 'Kiện Tướng', 160, 75, 72, 52, 40, 42, 45, 62, 45, 78, 68, 50, 60, 'VALIANT', 'Một trong Bát Kiện Tướng kiêu dũng của Lữ Bố, từng dấy binh đánh úp Hạ Phì sa trường.'),
    (217, '曹性', 'Thần Tiễn', 165, 82, 75, 60, 45, 50, 48, 68, 55, 80, 82, 90, 70, 'VALIANT', 'Dũng tướng Lữ Bố có tài bắn cung xuất quỷ nhập thần, người bắn một mũi tên mù mắt Hạ Hầu Đôn tại Hạ Phì.'),
    (218, '成廉', 'Kiêu Kỵ', 162, 82, 78, 52, 40, 45, 45, 66, 48, 84, 78, 62, 68, 'VALIANT', 'Tướng cưỡi ngựa tâm phúc theo Lữ Bố từ thời Tinh Châu, xung phong hãm trận muôn người không địch nổi.'),
    (219, '魏续', 'Kiện Tướng', 165, 76, 74, 55, 48, 50, 52, 68, 48, 78, 72, 55, 65, 'PRAGMATIC', 'Tướng lĩnh thân thích Lữ Bố, sau trói Trần Cung mở cổng thành Hạ Phì hàng Tào Tháo.'),
    (220, '宋宪', 'Kiện Tướng', 162, 75, 74, 54, 46, 48, 50, 66, 48, 78, 72, 54, 64, 'PRAGMATIC', 'Võ tướng Lữ Bố, sau chém phản tướng quy thuận Tào Tháo, tử trận dưới chân đao Nhan Lương tại Bạch Mã.'),
    (221, '侯成', 'Hiệu Úy', 160, 74, 72, 52, 45, 48, 60, 68, 50, 76, 70, 56, 65, 'PRAGMATIC', 'Võ tướng coi quản chiến mã của Lữ Bố, người trộm ngựa Xích Thố tạo bước ngoặt trận Hạ Phì.'),
    (222, '陈登', 'Nguyên Long', 170, 76, 88, 93, 89, 86, 75, 88, 65, 75, 92, 94, 82, 'SCHOLARLY', 'Tài hoa xuất chúng Từ Châu, văn võ song toàn, hai lần dùng kế đánh tan đại quân Tôn Sách bảo vệ Quảng Lăng.'),
    (223, '陈珪', 'Hán Du', 130, 30, 68, 89, 88, 90, 70, 78, 50, 55, 90, 92, 80, 'SCHOLARLY', 'Nguyên lão Từ Châu cha của Trần Đăng, dùng kế ly gián tài tình phá tan liên minh Lữ Bố và Viên Thuật.'),
    (224, '麋夫人', 'Mi Thị', 175, 25, 45, 76, 75, 82, 85, 70, 65, 58, 95, 80, 72, 'HONORABLE', 'Em gái Mi Trúc, phu nhân Lưu Bị, tại dốc Tràng Bản vì bảo toàn mạng sống cho ấu chúa A Đẩu đã trầm mình xuống giếng.'),
    (225, '甘夫人', 'Chiêu Liệt', 177, 20, 42, 78, 76, 85, 70, 68, 65, 60, 88, 84, 90, 'BENEVOLENT', 'Sinh mẫu của Hậu Chủ Lưu Thiền, dung nhan đoan trang như ngọc, tính tình dịu dàng nâng đỡ gia đình.'),
    (226, '张纮', 'Tử Cương', 153, 25, 72, 91, 93, 88, 72, 85, 55, 65, 90, 90, 80, 'SCHOLARLY', 'Cùng Trương Chiêu xưng Giang Đông Nhị Trương, quân sư đắc lực của Tôn Sách, người khuyên Tôn Quyền dời đô về Kiến Nghiệp.'),
    (227, '顾雍', 'Nguyên Thán', 168, 20, 75, 88, 95, 86, 80, 92, 50, 68, 92, 88, 82, 'SCHOLARLY', 'Học trò Sái Ung, làm Thừa tướng Đông Ngô 19 năm không rượu không cười cợt, thi hành luật pháp công minh an định giang sơn.'),
    (228, '笮融', 'Phật Đồ', 160, 60, 65, 68, 60, 72, 84, 82, 70, 70, 68, 70, 72, 'AMBITIOUS', 'Quản lý vận tải lương thảo Từ Châu, người cho xây dựng nhiều ngôi chùa lớn đầu tiên tại vùng duyên hải phương nam.'),
    (229, '司马徽', 'Đức Thao', 145, 20, 65, 98, 85, 94, 60, 70, 70, 60, 98, 99, 85, 'SCHOLARLY', 'Thủy Kính tiên sinh, danh sĩ ẩn dật tinh thông nhân sự, câu nói hảo hảo tiên sinh, người chỉ lối Lưu Bị tìm Ngọa Long.'),
    (230, '庞德公', 'Sơn Khách', 140, 20, 60, 96, 84, 90, 58, 68, 65, 62, 96, 98, 82, 'SCHOLARLY', 'Bác ruột Bàng Thống, bậc cao sĩ Kinh Châu từ chối làm quan, xưng tụng Gia Cát là Ngọa Long, Bàng Thống là Phượng Sồ.'),
    (231, '黄承彦', 'Cao Sĩ', 148, 25, 62, 94, 80, 85, 65, 75, 95, 65, 94, 95, 80, 'SCHOLARLY', 'Nhạc phụ Gia Cát Lượng, bậc hiền sĩ tinh thông kỳ môn độn giáp, người dắt Lục Tốn thoát khỏi mê hồn Bát Trận Đồ.'),
    (232, '韩嵩', 'Đức Cao', 155, 30, 68, 84, 86, 85, 65, 76, 50, 64, 88, 82, 75, 'HONORABLE', 'Danh sĩ Kinh Châu Bát Tuấn, can ngăn Lưu Biểu liên minh Tào Tháo bảo vệ thái bình, không sợ chết can gián chúa công.'),
    (233, '刘琦', 'Trưởng Tử', 175, 45, 70, 72, 74, 76, 62, 72, 48, 55, 78, 70, 72, 'BENEVOLENT', 'Con trưởng Lưu Biểu, theo kế Gia Cát Lượng ra trấn giữ Giang Hạ thoát hiểm, tiếp viện quân lương cho Lưu Bị sau Xích Bích.'),
    (234, '刘琮', 'Thứ Tử', 182, 40, 62, 68, 70, 72, 60, 68, 45, 58, 65, 65, 65, 'CAUTIOUS', 'Con thứ Lưu Biểu được mẹ kế họ Thái lập kế tự, sau mang toàn cõi Kinh Châu đầu hàng Tào Tháo.'),
    (235, '蔡瑁', 'Đức Khuê', 158, 75, 83, 76, 78, 75, 72, 85, 60, 76, 74, 76, 72, 'PRAGMATIC', 'Đại đô đốc thủy quân Kinh Châu em rể Lưu Biểu, huấn luyện thủy binh tinh nhuệ khiến Tào Tháo hết mực nể sợ.'),
    (236, '张允', 'Đô Đốc', 160, 74, 80, 74, 75, 72, 70, 82, 58, 75, 72, 74, 70, 'PRAGMATIC', 'Phó đô đốc thủy quân Kinh Châu cháu gọi Lưu Biểu bằng cậu, phối hợp Thái Mạo cai quản chiến thuyền Kinh Hán.'),
    (237, '蒯良', 'Tử Nhu', 150, 35, 78, 88, 86, 84, 68, 78, 50, 62, 86, 88, 74, 'SCHOLARLY', 'Mưu sĩ hàng đầu của Lưu Biểu, bày mưu đặt bẫy bắn chết Giang Đông mãnh hổ Tôn Kiên tại Hiện Sơn.'),
    (238, '蒯越', 'Dị Độ', 154, 38, 76, 89, 88, 86, 70, 80, 52, 65, 88, 88, 76, 'SCHOLARLY', 'Em Quỳ Lương, bày mưu dẹp yên tông tặc giúp Lưu Biểu đơn thương độc mã định đoạt Kinh Châu, Tào Tháo hết lời khen ngợi.'),
    (239, '文聘', 'Trọng Nghiệp', 165, 86, 89, 75, 74, 72, 60, 82, 55, 88, 92, 78, 78, 'HONORABLE', 'Đại tướng trung dũng của Kinh Châu sau theo Ngụy, trấn thủ Giang Hạ mấy chục năm đánh lui Tôn Quyền nhiều trận.'),
    (240, '韩当', 'Nghĩa Công', 152, 85, 84, 68, 62, 65, 55, 78, 55, 86, 85, 70, 74, 'VALIANT', 'Tam triều lão tướng Đông Ngô theo phò Tôn Kiên Tôn Sách Tôn Quyền, công huân trác tuyệt nơi chiến hỏa Xích Bích.'),
    (241, '蒋钦', 'Công Dịch', 168, 84, 83, 72, 68, 70, 60, 78, 55, 84, 84, 72, 75, 'VALIANT', 'Dũng tướng Giang Đông tính tình giản dị cần kiệm, dũng lược xung phong đoạt thuyền địch trong trận Xích Bích.'),
    (242, '朱桓', 'Hưu Mục', 177, 86, 88, 78, 72, 70, 60, 82, 55, 86, 90, 78, 78, 'VALIANT', 'Danh tướng kiêu dũng Đông Ngô, chỉ huy vạn quân đại phá mấy vạn quân Tào Nhân tại Nhu Tu Khẩu.'),
    (243, '潘璋', 'Văn Khuê', 175, 83, 82, 68, 60, 62, 58, 75, 50, 84, 80, 70, 72, 'VALIANT', 'Dũng tướng tác chiến bạo liệt, người chỉ huy phục kích bắt sống Quan Vũ tại Lâm Thư.'),
    (244, '董袭', 'Nguyên Đại', 165, 84, 80, 60, 50, 52, 48, 74, 52, 88, 86, 65, 70, 'VALIANT', 'Thân hình tám thước dũng mãnh, đại tướng lầu thuyền chỉ huy hạm đội Xích Bích chiến đấu đến giọt máu cuối.'),
    (245, '吕范', 'Tử Hành', 160, 68, 84, 82, 86, 85, 88, 92, 60, 75, 88, 85, 82, 'PRAGMATIC', 'Bạn tri kỷ của Tôn Sách, bậc thầy quản lý tài chính hậu cần và điều động hạm đội thuyền bè Đông Ngô.'),
    (246, '诸葛瑾', 'Tử Du', 174, 65, 86, 89, 92, 94, 78, 88, 55, 72, 94, 90, 85, 'HONORABLE', 'Anh trai Gia Cát Lượng, bậc đại thần trung hậu bậc nhất Đông Ngô, giữ gìn liên minh Tôn Lưu qua mọi phong ba.'),
    (247, '阚泽', 'Đức Nhuận', 170, 30, 65, 90, 88, 92, 65, 75, 60, 65, 92, 90, 80, 'SCHOLARLY', 'Học sĩ uyên bác một mình sang doanh Tào dâng hàng thư giả của Hoàng Cái, không chút sợ hãi trước Tào Tháo.'),
    (248, '焦筹', 'Tiêu Kỵ', 165, 78, 76, 62, 50, 55, 52, 70, 50, 80, 76, 64, 68, 'VALIANT', 'Võ tướng thủy quân Đông Ngô, tuần tra bảo hộ thủy trại Xích Bích ngày đêm.'),
    (249, '骆统', 'Công Tích', 193, 75, 82, 85, 88, 84, 70, 82, 55, 78, 88, 84, 78, 'HONORABLE', 'Tướng lĩnh danh thần nho nhã Đông Ngô, dâng sớ can gián nhiều việc lớn giúp dân giàu nước mạnh.'),
    (250, '张温', 'Huệ Thứ', 193, 35, 68, 86, 85, 92, 72, 78, 55, 64, 86, 86, 78, 'SCHOLARLY', 'Danh sĩ phong nhã Giang Đông, làm sứ giả sang Thục khiến triều đình Gia Cát Lượng hết mực khâm phục.'),
    (251, '虞翻', 'Trọng Tường', 164, 65, 78, 92, 82, 78, 60, 75, 88, 72, 92, 92, 75, 'SCHOLARLY', 'Học giả Dịch học danh tiếng, tính cương trực, từng dùng tài biện thuyết thu phục nhiều thành trì cho Tôn Sách.'),
    (252, '朱骑', 'Thợ Thuyền', 168, 45, 60, 68, 55, 60, 75, 82, 92, 76, 78, 80, 72, 'PRAGMATIC', 'Bậc thầy đóng chiến thuyền lâu năm của thủy quân Đông Ngô, chế tạo lầu thuyền Mông Xung bền chắc.'),
    (253, '郑度', 'Mưu Sĩ', 165, 38, 72, 88, 82, 75, 60, 78, 50, 65, 88, 86, 70, 'PRAGMATIC', 'Mưu sĩ Ích Châu từng hiến kế tiêu thổ kháng chiến khiến Lưu Bị cực kỳ lo ngại khi phạt Ba Thục.'),
    (254, '江津', 'Hoa Tiêu', 160, 60, 70, 70, 55, 68, 76, 92, 70, 78, 80, 82, 75, 'PRAGMATIC', 'Lão hoa tiêu cả đời sống trên sông Trường Giang, thuộc từng bãi cạn xoáy nước bến Xích Bích Ô Lâm.'),
    (255, '霍峻', 'Trọng Mạc', 178, 84, 88, 78, 72, 68, 55, 82, 55, 88, 98, 80, 80, 'HONORABLE', 'Võ tướng dũng liệt Thục Hán chỉ cầm mấy trăm quân tử thủ Hà Manh thành trước vạn quân Lưu Chương hơn một năm ròng.'),
    (256, '霍弋', 'Thiệu Tiên', 205, 82, 85, 80, 82, 84, 65, 82, 55, 84, 88, 80, 80, 'HONORABLE', 'Con Hoắc Tuấn, trấn thủ Nam Trung vỗ về các bộ lạc dị tộc, dẹp yên phản loạn an định biên cương phía nam.'),
    (257, '向朗', 'Cự Đạt', 167, 35, 75, 86, 88, 84, 68, 82, 60, 68, 88, 88, 78, 'SCHOLARLY', 'Trọng thần Thục Hán, chăm chỉ học hành tàng thư phong phú bậc nhất, giám sát quân luật thời thừa tướng Khổng Minh.'),
    (258, '向宠', 'Trung Bộ', 190, 82, 86, 78, 75, 76, 60, 84, 55, 84, 88, 78, 78, 'HONORABLE', 'Cháu Hướng Lãng được Gia Cát Lượng khen ngợi trong Xuất Sư Biểu là tính tình hiền lành hiểu việc quân sự.'),
    (259, '金旋', 'Vũ Lăng', 158, 70, 72, 65, 70, 72, 62, 70, 50, 74, 72, 65, 68, 'PRAGMATIC', 'Thái thú Vũ Lăng một trong bốn quận Kinh Nam thời sơ kỳ Tam Quốc, cát cứ quản lý địa phương.'),
    (260, '刘度', 'Linh Lăng', 155, 65, 70, 68, 72, 74, 65, 70, 50, 70, 72, 68, 70, 'BENEVOLENT', 'Thái thú Linh Lăng lấy lòng nhân đãi dân, sau khi hàng Lưu Bị vẫn được giữ chức an định trăm họ.'),
    (261, '赵范', 'Quế Dương', 160, 68, 72, 70, 74, 78, 72, 72, 52, 72, 74, 70, 72, 'PRAGMATIC', 'Thái thú Quế Dương cùng quê kết nghĩa huynh đệ với Triệu Vân, quản lý giao thương trù phú Kinh Nam.'),
    (262, '韩玄', 'Trường Sa', 155, 68, 72, 66, 68, 65, 65, 72, 50, 74, 70, 65, 68, 'AMBITIOUS', 'Thái thú Trường Sa nắm giữ dũng tướng Hoàng Trung và Ngụy Diên, quản trị bờ cõi sông Tương Giang rộng lớn.'),
    (263, '刘贤', 'Thiếu Chủ', 180, 76, 75, 65, 60, 64, 55, 68, 48, 78, 75, 65, 68, 'VALIANT', 'Con trai Lưu Độ, dũng cảm đem quân kháng cự quân Thục, sau quy phục một lòng phò tá Lưu Hoàng Thúc.'),
    (264, '邢道荣', 'Khai Sơn', 170, 84, 76, 50, 38, 42, 45, 65, 45, 88, 80, 52, 68, 'FIERCE', 'Dũng tướng số một vùng Kinh Nam tay cầm khai sơn phủ vạn người khó địch, giao đấu dũng mãnh cùng Trương Phi.'),
    (265, '鲍隆', 'Hiệu Úy', 165, 78, 74, 58, 45, 50, 48, 68, 48, 80, 74, 58, 65, 'VALIANT', 'Võ tướng Quế Dương từng tay không giết hai con hổ dữ trên núi, dũng cảm xung trận sa trường.'),
    (266, '陈应', 'Tiên Phong', 165, 79, 74, 58, 45, 50, 48, 68, 55, 80, 76, 82, 66, 'VALIANT', 'Tướng tiên phong Quế Dương giỏi dùng phi xoa phóng đâm bách phát bách trúng nơi trận tiền.'),
    (267, '杨龄', 'Lão Tướng', 158, 78, 75, 55, 42, 48, 45, 68, 45, 80, 75, 56, 65, 'VALIANT', 'Chiến tướng tiên phong dưới trướng Hàn Huyền, hăng hái dẫn binh xuất thành cự địch.'),
    (268, '樊氏', 'Phàn Nương', 170, 22, 45, 80, 74, 92, 75, 65, 78, 52, 85, 88, 86, 'BENEVOLENT', 'Giai nhân tuyệt sắc vùng Kinh Nam, phong tư yểu điệu đoan trang hiền thục, Triệu Phạm toan gả cho Triệu Vân.'),
    (269, '沙摩柯', 'Man Vương', 180, 89, 85, 55, 45, 58, 52, 74, 50, 95, 88, 72, 75, 'FIERCE', 'Hùng trưởng Ngũ Khê Man râu đỏ mắt xanh tay cầm thiết tật lê cốt đóa, người bắn chết dũng tướng Cam Ninh tại Di Lăng.'),
    (270, '茶商翁', 'Trà Lão', 160, 42, 60, 72, 68, 85, 92, 88, 65, 70, 78, 85, 82, 'PRAGMATIC', 'Đại thương nhân chi phối mạng lưới thu mua và vận chuyển danh trà Kinh Tương đi khắp mười lăm châu quận.'),
    (271, '孙鲁班', 'Đại Hổ', 200, 40, 75, 88, 90, 86, 75, 78, 60, 68, 92, 88, 80, 'AMBITIOUS', 'Trưởng công chúa con gái Tôn Quyền và Bộ Luyện Sư, thông minh quyền biến, khuynh đảo chính trường Đông Ngô nhiều năm.'),
    (272, '孙鲁育', 'Tiểu Hổ', 204, 25, 60, 82, 84, 88, 72, 72, 65, 62, 86, 84, 85, 'BENEVOLENT', 'Công chúa thứ hai của Tôn Quyền, tính tình hiền dịu nhu hòa, thương yêu trăm họ và hòa thuận gia tộc.'),
    (273, '陆抗', 'Ấu Tiết', 226, 82, 95, 93, 89, 86, 70, 88, 60, 82, 94, 90, 84, 'HONORABLE', 'Con Lục Tốn, danh tướng vĩ đại cuối cùng của thời Tam Quốc, cùng Dương Hỗ tạo nên tình bạn quân tử biên cương lưu danh.'),
    (274, '全琮', 'Tử Hoàng', 198, 82, 85, 82, 86, 84, 75, 82, 55, 82, 88, 82, 80, 'HONORABLE', 'Đại tướng danh môn Giang Đông, phò tá Tôn Quyền nhiều năm lập chiến công hiển hách đánh lui Ngụy Doanh.'),
    (275, '朱异', 'Quý Văn', 210, 82, 82, 78, 74, 72, 65, 80, 52, 82, 86, 76, 76, 'VALIANT', 'Con danh tướng Chu Hoàn, dũng cảm quyết đoán, chỉ huy thủy lục quân Đông Ngô cứu viện Thọ Xuân.'),
    (276, '诸葛恪', 'Nguyên Tốn', 203, 75, 88, 92, 86, 85, 70, 85, 60, 78, 88, 88, 82, 'AMBITIOUS', 'Con Gia Cát Cẩn, tài năng mẫn tiệp ứng đối thần sầu, chỉ huy Đông Hưng đại thắng phá tan quân Ngụy.'),
    (277, '阎圃', 'Công Tào', 165, 35, 75, 88, 86, 85, 72, 80, 55, 68, 90, 88, 80, 'SCHOLARLY', 'Quân sư chủ chốt của Trương Lỗ, luôn can ngăn việc xưng vương bảo toàn thế lực, Tào Tháo phong liệt hầu.'),
    (278, '杨松', 'Tham Kim', 160, 25, 55, 72, 65, 80, 86, 78, 50, 55, 60, 72, 70, 'PRAGMATIC', 'Đại thần Hán Trung mê tiền của, khuyên Trương Lỗ nghi kỵ Mã Siêu và Bàng Đức, tạo cơ hội cho đối phương.'),
    (279, '杨任', 'Đại Tướng', 168, 84, 82, 65, 52, 55, 48, 72, 48, 84, 88, 68, 72, 'VALIANT', 'Chiến tướng dũng cảm nhất Hán Trung, dũng mãnh giao chiến cùng Tào Tháo tại Dương Bình Quan.'),
    (280, '杨昂', 'Hiệu Úy', 165, 78, 76, 58, 48, 52, 48, 68, 45, 80, 75, 62, 68, 'VALIANT', 'Võ tướng Hán Trung hiệp thủ Dương Bình Quan chống giặc, xung phong trận mạc can trường.'),
    (281, '张卫', 'Tử Thủ', 165, 80, 82, 68, 60, 62, 55, 74, 50, 82, 80, 68, 70, 'VALIANT', 'Em trai Trương Lỗ chỉ huy mấy vạn quân kiên quyết không hàng Tào, tử thủ đường núi Hán Xuyên.'),
    (282, '庞羲', 'Ba Tây', 155, 68, 78, 76, 80, 78, 72, 78, 52, 74, 78, 74, 74, 'PRAGMATIC', 'Đại thần giúp Lưu Yên và Lưu Chương an định đất Thục, nhiều năm trấn thủ Ba Tây ngăn Trương Lỗ.'),
    (283, '雷铜', 'Mãnh Tướng', 170, 82, 78, 55, 45, 48, 48, 70, 48, 85, 82, 62, 70, 'VALIANT', 'Mãnh tướng Thục Hán theo Lưu Bị đoạt Hán Trung, dũng cảm xung phong trận tiền đoạt ải.'),
    (284, '吴兰', 'Kỵ Tướng', 172, 81, 78, 56, 46, 50, 48, 70, 48, 84, 80, 64, 70, 'VALIANT', 'Võ tướng kỵ binh Thục Hán dũng mãnh, tiên phong đại chiến cùng Tào Hồng Tào Hưu tại Hạ Biện.'),
    (285, '吴懿', 'Tử Viễn', 170, 82, 86, 78, 80, 78, 65, 82, 55, 84, 88, 80, 80, 'HONORABLE', 'Đại tướng quân Thục Hán anh rể Tiên Chủ Lưu Bị, trấn thủ Hán Trung vững như bàn thạch.'),
    (286, '吴班', 'Nguyên Hùng', 175, 82, 83, 70, 65, 68, 55, 78, 50, 84, 84, 72, 75, 'VALIANT', 'Tướng lĩnh kiêu dũng kiên cường của Thục Hán, tiên phong đánh tan quân Ngô giai đoạn đầu trận Di Lăng.'),
    (287, '王平', 'Tử Quân', 185, 84, 90, 82, 78, 72, 60, 85, 55, 88, 95, 86, 82, 'HONORABLE', 'Thống soái tinh nhuệ Vô Đương Phi Quân, người duy nhất giữ vững trận địa tại Nhai Đình bảo toàn rút lui.'),
    (288, '邓芝', 'Bá Miêu', 178, 75, 84, 88, 92, 96, 75, 85, 55, 80, 94, 90, 85, 'HONORABLE', 'Đại thần kiệt xuất Thục Hán một tay nối lại liên minh Thục Ngô, tính tình thanh liêm thẳng thắn.'),
    (289, '张翼', 'Bá Cung', 190, 82, 85, 78, 82, 78, 65, 82, 55, 84, 88, 80, 80, 'HONORABLE', 'Đại tướng Thục Hán tính tình cẩn trọng quy củ, nhiều lần theo Khương Duy phạt Bắc, tử tiết vì nước.'),
    (290, '张嶷', 'Bá Kỳ', 192, 83, 85, 78, 76, 80, 62, 80, 52, 84, 90, 80, 78, 'HONORABLE', 'Danh tướng Thục Hán dẹp yên các bộ lạc Nam Man vỗ về trăm họ, tử chiến sa trường bảo vệ non sông.'),
    (291, '栈道老夫', 'Hiểm Đạo', 160, 50, 65, 68, 55, 68, 78, 94, 75, 80, 82, 85, 76, 'PRAGMATIC', 'Lão xa phu cả đời gắn bó với đường ván gỗ sạn đạo hiểm trở từ Hán Trung sang Xuyên Thục, đi lại như bay.'),
    (292, '蒋琬', 'Công Diễm', 188, 65, 88, 93, 96, 92, 82, 94, 60, 80, 96, 94, 88, 'SCHOLARLY', 'Người kế thừa đầu tiên của Gia Cát Lượng, cúc cung tận tụy điều hành Thục Hán thái bình thịnh trị suốt mười mấy năm.'),
    (293, '费祎', 'Văn Vĩ', 192, 60, 85, 94, 95, 96, 80, 90, 60, 78, 94, 95, 86, 'BENEVOLENT', 'Thừa tướng Thục Hán tính tình khiêm hòa vui vẻ, xử lý việc triều chính thần tốc, gìn giữ non sông vững chãi.'),
    (294, '董允', 'Hưu Chi', 190, 45, 78, 90, 94, 88, 70, 85, 55, 75, 96, 94, 84, 'HONORABLE', 'Một trong Thục Hán Tứ Anh, làm quan thanh liêm cương trực, ngăn chặn hoạn quan Hoàng Hạo lộng quyền.'),
    (295, '谯周', 'Doãn Nam', 201, 20, 50, 91, 82, 84, 60, 65, 55, 60, 84, 94, 78, 'SCHOLARLY', 'Đại học giả uyên bác nhất đất Thục, học trò môn sinh đông đúc, am tường thiên văn lịch sử và dịch thuật.'),
    (296, '黄权', 'Công Hành', 170, 75, 88, 90, 86, 82, 70, 85, 55, 80, 90, 88, 80, 'HONORABLE', 'Mưu thần danh tướng hiến kế đoạt Hán Trung, sau trận Di Lăng đường về bị cắt đứt sang Ngụy, Lưu Bị vẫn hết lời khen ngợi.'),
    (297, '孟达', 'Tử Độ', 172, 80, 82, 84, 78, 82, 75, 80, 55, 80, 75, 80, 72, 'PRAGMATIC', 'Võ tướng có tài văn học thao lược đất Ba Thục, cai quản Thượng Dung ba quận hiểm yếu.'),
    (298, '李严', 'Chính Phương', 170, 82, 87, 88, 88, 82, 75, 88, 60, 84, 85, 84, 78, 'AMBITIOUS', 'Đại thần thác cô cùng Gia Cát Lượng, văn võ toàn tài, giỏi tổ chức đồn điền và huấn luyện quân giới tinh xảo.'),
    (299, '秦宓', 'Tử Sắc', 175, 25, 55, 89, 82, 95, 68, 70, 55, 62, 90, 94, 80, 'SCHOLARLY', 'Đệ nhất tài hùng biện đất Thục, từng đối đáp lưu loát khiến sứ thần Đông Ngô Trương Ôn phải cúi đầu bái phục.'),
    (300, '吕乂', 'Quý Dương', 180, 30, 74, 85, 91, 82, 82, 88, 55, 68, 92, 88, 80, 'HONORABLE', 'Thượng thư lệnh Thục Hán quản trị quan chế liêm khiết giản dị, chấp pháp nghiêm cẩn được trăm quan kính sợ.');

INSERT OR IGNORE INTO np_skill (npc_id, code, name_vi, category, tier, description, effect_summary) VALUES
    (128, 'that_bo', 'Thất Bộ', 'special', 5, 'Bảy bước thành thơ, văn chương quán thế.', 'Tăng cực đại danh vọng và cảm hứng thi phú'),
    (129, 'hoang_tu', 'Hoàng Tu', 'martial', 4, 'Võ nghệ tuyệt luân, xung kích phá trận sa trường.', '+18% chiến lực kỵ binh sa trường'),
    (130, 'hien_hau', 'Hiền Hậu', 'governance', 4, 'Cần kiệm trì gia, ổn định gia quyến và hậu phương.', 'Giảm 20% chi phí gia quyến và tăng ổn định phủ đệ'),
    (131, 'thanh_liem', 'Thanh Liêm', 'governance', 4, 'Thanh liêm chính trực, pháp độ nghiêm minh.', 'Tăng trị an thành thị và giảm tham ô quan phủ'),
    (132, 'dien_tac', 'Điển Tắc', 'governance', 4, 'Nho học uyên bác, thông đạt thể chế bang quốc.', 'Gia tăng điểm văn học và danh vọng sĩ tộc'),
    (133, 'cuu_pham', 'Cửu Phẩm', 'governance', 5, 'Kiến thiết chế độ cửu phẩm tuyển chọn nhân tài.', 'Tăng chất lượng chiêu mộ gia thần và môn khách'),
    (134, 'nha_luong', 'Nhã Lượng', 'governance', 4, 'Cương trực tiết tháo, không sợ cường quyền.', 'Tăng uy tín chính trị và phòng ngự hối lộ'),
    (135, 'tram_tham', 'Trầm Thâm', 'strategist', 5, 'Thâm mưu đại độ, trấn áp phản nghịch.', 'Tăng mạnh sĩ khí quân ngũ và hóa giải bạo loạn'),
    (136, 'chieu_tam', 'Chiêu Tâm', 'strategist', 5, 'Tài trí kiệt xuất, mưu định giang sơn thống nhất.', 'Tăng cơ hội thành công của mọi đại mưu lược'),
    (137, 'ma_thuong', 'Mã Thương', 'commerce', 4, 'Mạng lưới buôn bán chiến mã rộng khắp phương bắc.', 'Giảm 15% giá mua chiến mã và xe vận chuyển'),
    (138, 'tay_luong_ky', 'Tây Lương Kỵ', 'martial', 5, 'Kỵ binh Tây Lương xung phong dũng mãnh.', '+20% tốc độ và sức tấn công kỵ binh sa trường'),
    (139, 'cuu_khuc', 'Cửu Khúc', 'strategist', 4, 'Biến ảo khôn lường nơi sa trường hiểm địa.', 'Giảm 30% tổn thất khi bị phục kích đường núi'),
    (140, 'doat_mau', 'Đoạt Mâu', 'martial', 4, 'Thương mâu sắc bén áp đảo đơn đấu.', '+18% sát thương đơn đấu lôi đài'),
    (141, 'hao_tam', 'Hào Tâm', 'commerce', 3, 'Giao lưu rộng rãi hào kiệt bốn phương.', 'Tăng tốc độ thu thập tin tức thị trường Tây Bắc'),
    (142, 'phi_ky', 'Phi Kỵ', 'martial', 3, 'Kỵ binh thần tốc đột kích doanh trại.', '+12% tốc độ hành quân đường sa mạc'),
    (143, 'dung_tien', 'Dũng Tiến', 'martial', 3, 'Xung trận hãm địch trực diện.', '+12% sát thương khi công đồn'),
